        assert "application/json" in res_5.headers["content-type"]
        assert res_5.json()["ca_certificate"] == "-----BEGIN CERTIFICATE-----\nMIIBbzCCASGgAwIBAgIUAccQKmJirW0enyVFckQfZswyVD8wBQYDK2VwMDQxIzAh\nBgNVBAMMGkJBTUYgQ2VydGlmaWNhdGUgQXV0aG9yaXR5MQ0wCwYDVQQKDARCQU1G\nMB4XDTI2MDkzMDA2MDQyMFoXDTM2MDkyNzA2MDQyMFowNDEjMCEGA1UEAwwaQkFN\nRiBDZXJ0aWZpY2F0ZSBBdXRob3JpdHkxDTALBgNVBAoMBEJBTUYwKjAFBgMrZXAD\nIQB0dfwwwz50bI14nqV+P6gnIlKEfFhUifwwATWaQdxYe6NFMEMwEgYDVR0TAQH/\nBAgwBgEB/wIBADAOBgNVHQ8BAf8EBAMCAYYwHQYDVR0OBBYEFHG976FzPBGd/u4k\nMh/XL6rWTYULMAUGAytlcANBANm5MNq4PKmxyCDt5njRzPQDftCeZ57ZHozUivZL\n+UBBBaHAygle4VGuxLhnikFmFiPQ7sk/wEOuUI5xFRhsSAY=\n-----END CERTIFICATE-----"
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/tokens/{token_id}'.
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_6 = requests \
                .delete(self.baseUrlOfSut + "/api/v1/tokens/LRAa_Um",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_6.status_code == 401
        assert "Bearer" in res_6.headers["www-authenticate"]
        assert "application/json" in res_6.headers["content-type"]
        assert res_6.json()["detail"] == "Invalid or expired session"
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/agents/{agent_id}/instance/{instance_id}/offline'.
        headers = {}
        headers["X-Bamf-Client-Cert"] = "null"
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_7 = requests \
                .post(self.baseUrlOfSut + "/api/v1/agents/_0E_cvcUth0QjUO/instance/XAKowsIL8LO8Nb/offline",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_7.status_code == 401
        assert "www-authenticate" not in res_7.headers
        assert "application/json" in res_7.headers["content-type"]
        assert res_7.json()["detail"] == "Invalid certificate format"


